namespace CourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

public class Course
{
    public int Id { get; set; }
    public int DepartmentId { get; set; }
    public string DepartmentCode { get; set; } = string.Empty;
    public string CourseNumber { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }

    public string FullCode => $"{DepartmentCode} {CourseNumber}";
}

public class EnrollmentRequest
{
    public string StudentName { get; set; } = string.Empty;
    public string StudentId { get; set; } = string.Empty;
    public int CourseId { get; set; }
}

using CourseCatalog.Models;

namespace CourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollments = new();

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Name = "English", Code = "ENG", Description = "Study of literature, writing, and critical analysis." },
            new() { Id = 5, Name = "History", Code = "HIST", Description = "Study of past events, civilizations, and their impact." }
        };

        _courses = new List<Course>
        {
            new() { Id = 1, DepartmentId = 1, DepartmentCode = "CS", CourseNumber = "101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education. She holds a Ph.D. from MIT and has published extensively on programming pedagogy.", IsFeatured = true },
            new() { Id = 2, DepartmentId = 1, DepartmentCode = "CS", CourseNumber = "201", Title = "Data Structures and Algorithms", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs) and algorithm design techniques (sorting, searching, dynamic programming).", Credits = 4, Schedule = "Tue/Thu 10:30 AM–12:00 PM", InstructorName = "Dr. James Rodriguez", InstructorBio = "Dr. Rodriguez specializes in algorithm optimization and has contributed to several open-source projects. He earned his Ph.D. from Stanford University.", IsFeatured = true },
            new() { Id = 3, DepartmentId = 1, DepartmentCode = "CS", CourseNumber = "310", Title = "Database Systems", Description = "Design and implementation of relational databases, SQL, normalization, transaction processing, and introduction to NoSQL systems.", Credits = 3, Schedule = "Mon/Wed 2:00–3:30 PM", InstructorName = "Dr. Maria Gonzalez", InstructorBio = "Dr. Gonzalez worked at Oracle for 10 years before joining academia. Her research focuses on distributed database systems." },
            new() { Id = 4, DepartmentId = 1, DepartmentCode = "CS", CourseNumber = "450", Title = "Machine Learning", Description = "Introduction to machine learning concepts including supervised and unsupervised learning, neural networks, and model evaluation.", Credits = 4, Schedule = "Tue/Thu 1:00–2:30 PM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education. She holds a Ph.D. from MIT and has published extensively on programming pedagogy.", IsFeatured = true },
            new() { Id = 5, DepartmentId = 2, DepartmentCode = "MATH", CourseNumber = "101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Alan Park", InstructorBio = "Dr. Park is an award-winning educator who has taught calculus for over 20 years. He is known for making complex concepts accessible to all students." },
            new() { Id = 6, DepartmentId = 2, DepartmentCode = "MATH", CourseNumber = "201", Title = "Linear Algebra", Description = "Vectors, matrices, linear transformations, eigenvalues, and applications to computer science and data analysis.", Credits = 3, Schedule = "Tue/Thu 9:00–10:30 AM", InstructorName = "Dr. Lisa Wang", InstructorBio = "Dr. Wang's research is in applied mathematics with applications in machine learning. She received her Ph.D. from Caltech.", IsFeatured = true },
            new() { Id = 7, DepartmentId = 2, DepartmentCode = "MATH", CourseNumber = "301", Title = "Probability and Statistics", Description = "Probability theory, random variables, distributions, hypothesis testing, and regression analysis.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", InstructorName = "Dr. Alan Park", InstructorBio = "Dr. Park is an award-winning educator who has taught calculus for over 20 years. He is known for making complex concepts accessible to all students." },
            new() { Id = 8, DepartmentId = 3, DepartmentCode = "PHYS", CourseNumber = "101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes laboratory component.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM + Lab Thu 2:00–4:00 PM", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is an experimental physicist with research in condensed matter physics. He emphasizes hands-on learning in his courses." },
            new() { Id = 9, DepartmentId = 3, DepartmentCode = "PHYS", CourseNumber = "201", Title = "General Physics II", Description = "Electricity, magnetism, optics, and modern physics. Includes laboratory component.", Credits = 4, Schedule = "Tue/Thu 11:00 AM–12:30 PM + Lab Fri 2:00–4:00 PM", InstructorName = "Dr. Emily Foster", InstructorBio = "Dr. Foster is a theoretical physicist specializing in quantum mechanics. She has been recognized for excellence in undergraduate teaching." },
            new() { Id = 10, DepartmentId = 4, DepartmentCode = "ENG", CourseNumber = "101", Title = "College Writing", Description = "Develop critical reading and writing skills through analysis of diverse texts. Emphasis on argument construction and revision.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Prof. Diana Hughes", InstructorBio = "Prof. Hughes is a published author and writing instructor with expertise in rhetoric and composition studies.", IsFeatured = true },
            new() { Id = 11, DepartmentId = 4, DepartmentCode = "ENG", CourseNumber = "250", Title = "American Literature", Description = "Survey of American literature from the colonial period to the present, examining major literary movements and cultural contexts.", Credits = 3, Schedule = "Tue/Thu 2:00–3:30 PM", InstructorName = "Dr. Michael Torres", InstructorBio = "Dr. Torres specializes in 20th-century American fiction and has authored two books on the American novel." },
            new() { Id = 12, DepartmentId = 5, DepartmentCode = "HIST", CourseNumber = "101", Title = "World Civilizations", Description = "Survey of major world civilizations from ancient times to 1500 CE, examining political, social, and cultural developments.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Dr. Patricia Okafor", InstructorBio = "Dr. Okafor is a historian specializing in comparative ancient civilizations with fieldwork experience in West Africa and the Mediterranean." },
            new() { Id = 13, DepartmentId = 5, DepartmentCode = "HIST", CourseNumber = "205", Title = "Modern European History", Description = "Europe from the French Revolution to the present day, including industrialization, world wars, and European integration.", Credits = 3, Schedule = "Tue/Thu 10:30 AM–12:00 PM", InstructorName = "Dr. Heinrich Müller", InstructorBio = "Dr. Müller is a specialist in modern German and European history. He previously taught at the University of Heidelberg." }
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? search = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.FullCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public void SubmitEnrollment(EnrollmentRequest request)
    {
        _enrollments.Add(request);
    }
}

